from build_shard import *
E=[]
Q_PAGES={1:[3],2:[4,5],3:[6],4:[7],5:[8,9,11],6:[12,13],7:[14],8:[15],9:[16,17],10:[17],11:[18],12:[18],13:[19],14:[20,21],15:[22],16:[23],17:[24],18:[25]}
def add(key,codes,prompt,answer,criteria,**kw):E.append(dict(key=key,codes=codes,prompt=prompt,answer=answer,criteria=criteria,ms=[],concept=prompt.split('.')[0],status=kw.pop('status','A'),**kw))
def exclude(key,reason):E.append(dict(key=key,codes=[],status='C',ms=[],exclude=reason,concept=reason))
add('1:a',['A3.2.2'],'A production studio has editors, productions and supervisors. Each editor belongs to exactly one production; each production has one or more editors. Each supervisor oversees one or more productions; each production has exactly one supervisor. Construct an ERD showing the two relationships and cardinalities.','SUPERVISOR 1—many PRODUCTION; PRODUCTION 1—many EDITOR. Every production has one supervisor and every editor one production; minimum participation follows the stated one-or-more requirements.',[(1,'Correct supervisor–production cardinality/modality.'),(1,'Correct production–editor cardinality/modality.')])
add('1:b',['A3.1.1'],'Outline one benefit of storing recorded document changes in a relational database rather than separate uncoordinated files.','Centralized related records can be queried consistently, making it possible to retrieve a document’s change history without manually merging separate files.',[(1,'Concrete retrieval/consistency/reduced duplication benefit.'),(1,'Relevant change-history expansion.')])
add('1:c',['A3.3.6'],'Two clients read version7 of a database row. One commits a change, creating version8. Outline how comparing the saved version before the second update can prevent a lost update.','The database compares the second client’s saved version7 with current version8. It rejects or retries the stale update rather than overwriting the newer committed data.',[(1,'Detects stale row/version difference.'),(1,'Prevents overwrite by rejection/retry.')],status='B',adapt='Original timestamp ordering is narrowed to a supplied version-check mechanism illustrating transaction consistency/isolation; no particular timestamp protocol is required.')
add('1:d',['A3.3.6'],'Explain how transaction locking can prevent two clerks from overwriting each other’s edits to the same booking record.','A transaction obtains a suitable exclusive lock before updating the record. A competing writer waits or retries. The first change is committed before the next writer reads and updates the current value. Releasing locks at the appropriate transaction boundary preserves isolation and avoids a lost update.',[(1,'Lock before conflicting update.'),(1,'Other writer waits/retries.'),(1,'Update operates on current data in an ordered sequence.'),(1,'Commit/transaction boundary handled.'),(1,'Explains isolation/lost-update prevention.')])
add('1:e-i',['A3.3.6'],'Outline what database consistency means for a transaction that transfers an amount between two accounts.','Integrity rules remain satisfied before and after a valid transaction; for example, the combined balance is unchanged when the amount is debited from one account and credited to the other.',[(1,'Integrity constraints preserved.'),(1,'Correct contextual invariant/example.')])
add('1:e-ii',['A3.3.6'],'Describe how ROLLBACK can restore a consistent state when an unfinished transfer has debited one account but has not credited the other.','ROLLBACK undoes the uncommitted debit and other changes of that transaction. Both accounts return to their pre-transaction values, avoiding a half-completed transfer.',[(1,'Targets uncommitted transaction.'),(1,'Undoes its changes.'),(1,'Restores prior consistent balances.')],status='B',adapt='Replaces unrestricted database recovery methods with explicitly required transaction rollback.')
add('2:a',['A3.2.4'],'The table BUILD(BuildID, LeadID, ClientID, Title, Deadline) stores one row per uniquely numbered build. Suggest a primary key and justify it.','BuildID: it uniquely identifies each build, whereas a lead or client may be associated with several builds.',[(1,'BuildID.'),(1,'Explains uniqueness/no unnecessary composite fields.')],new_command='Suggest')
add('2:b',['A3.2.3'],'A database field Urgent has only the states yes and no. Outline a suitable data type.','Boolean, representing the two states as True and False without storing arbitrary text values.',[(1,'Boolean.'),(1,'Explains two-state representation.')],status='B')
sql='''SELECT c.ClientName, c.ContactNumber
FROM Client AS c JOIN Job AS j ON c.ClientID=j.ClientID
WHERE j.LeadName='Mira Sen' AND j.Priority='High';'''
add('2:c',['A3.3.2'],'Tables Client(ClientID,ClientName,ContactNumber) and Job(JobID,ClientID,LeadName,Priority) are provided. Construct SQL to return client names and contact numbers for High-priority jobs led by Mira Sen. Repeated rows are permitted.','One solution:\n'+sql,[(1,'Selects both required client fields.'),(1,'Uses Client and Job.'),(1,'Correct join on ClientID.'),(1,'Correct lead-name filter.'),(1,'High-priority filter combined with AND.')],status='B',adapt='Original query requires three tables; conversion retains join/filter reasoning using exactly two tables as specified in A3.3.2.',check='Executed SQLite query with matching and nonmatching jobs.',test_code='''import sqlite3
c=sqlite3.connect(':memory:')
c.executescript("CREATE TABLE Client(ClientID,ClientName,ContactNumber);CREATE TABLE Job(JobID,ClientID,LeadName,Priority);INSERT INTO Client VALUES(1,'Atlas','001'),(2,'Birch','002');INSERT INTO Job VALUES(1,1,'Mira Sen','High'),(2,2,'Mira Sen','Low');")
assert c.execute("SELECT c.ClientName,c.ContactNumber FROM Client c JOIN Job j ON c.ClientID=j.ClientID WHERE j.LeadName='Mira Sen' AND j.Priority='High'").fetchall()==[('Atlas','001')]''')
add('2:d',['A3.2.6'],'A training register has fields LearnerID,LearnerName,Level,EventID,CourseTitle,Provider,EventDate,Fee,Completed. LearnerID determines LearnerName and Level; EventID determines CourseTitle,Provider,EventDate and Fee; the pair LearnerID/EventID determines Completed. Construct a3NF schema, indicating primary and foreign keys.','LEARNER(LearnerID PK,LearnerName,Level); EVENT(EventID PK,CourseTitle,Provider,EventDate,Fee); ENROLMENT(LearnerID PK/FK,EventID PK/FK,Completed). The enrolment key is the pair of IDs.',[(1,'Learner table with correct dependency.'),(1,'Event table with correct dependency.'),(1,'Enrolment contains completion status.'),(1,'Correct composite enrolment key.'),(1,'Both foreign keys and no partial-key dependencies.')],status='B',adapt='Original table does not state all functional dependencies; supplied dependencies remove ambiguity about event cost and qualification/provider relationships.')
add('3:a',['A3.2.1'],'Outline the role of a conceptual schema when a clinic plans a new database.','It identifies the main entities and relationships at a high level, independently of a particular DBMS or physical storage arrangement.',[(1,'High-level entities/relationships.'),(1,'Independent of physical/DBMS implementation.')])
exclude('3:b','Data-dictionary terminology is not named in the2027 individual learning guidance; do not add it as a compulsory schema requirement.')
add('3:c',['A3.3.1'],'Describe the role of SQL DDL when implementing an agreed relational schema.','DDL defines tables and columns, assigns data types, and declares constraints such as primary/foreign keys so the database structure enforces the model.',[(1,'Creates/changes structures.'),(1,'Defines columns/types.'),(1,'Defines keys/constraints.')])
add('3:d',['A3.1.1'],'List three database security tasks that restrict unauthorized access to confidential records.','Authenticate users; assign least-privilege access permissions; review/revoke inappropriate access rights.',[(1,'Authentication.'),(1,'Permissions/roles.'),(1,'A distinct appropriate access-review/revocation task.')],status='B')
add('3:e',['A3.3.5'],'Explain why an organization could give an external auditor a read-only database view containing only the fields needed for an audit.','A view hides unnecessary details and exposes only relevant records/fields, reducing disclosure of personal data. A read-only view prevents the auditor from changing operational records. It can simplify the query interface while the organization retains control of underlying tables.',[(1,'Limited field/row exposure.'),(1,'Explains privacy/security benefit.'),(1,'Read-only prevents edits.'),(1,'Simplifies relevant audit access.'),(1,'Links controlled view to protected underlying data.')],status='B')
add('4:a',['A3.4.3'],'List three ways OLAP can support analysis of a retailer’s historical sales.','Summarize sales by region; compare sales over time; examine a selected product category in more detail.',[(1,'Aggregation by meaningful business dimension.'),(1,'Time comparison/trend analysis.'),(1,'More detailed contextual analysis.')],status='B')
add('4:b',['A3.4.2'],'Define a data warehouse.','An integrated, subject-oriented collection of historical data optimized for analysis and decision support.',[(1,'Integrated historical/subject-oriented analytical data store.')],new_command='Define')
add('4:c',['A4.2.1'],'Explain why inconsistent formats, duplicated observations and missing values should be addressed before a dataset is used to train a prediction model.','Formats must be made consistent so equivalent values are interpreted alike. Duplicate observations can over-weight repeated cases and should be consolidated or removed. Missing values need a justified treatment, such as imputation or deletion, so they do not distort training or cause invalid processing.',[(1,'Consistent-format treatment.'),(1,'Explains comparability/model effect.'),(1,'Duplicate handling.'),(1,'Explains distorted weighting.'),(1,'Suitable missing-value treatment with relevant purpose.')],status='B',adapt='Retains transformation/cleaning reasoning while replacing ETL implementation detail with required ML data preparation.')
add('4:d',['A4.3.2'],'Describe how a supervised decision tree could classify a new software test run as likely to fail or likely to pass.','Train on labelled past runs with input features and pass/fail outcomes. The tree learns feature-based splits; the new run follows the applicable decisions to a leaf that provides a class prediction. Evaluate on independent labelled examples.',[(1,'Labelled training data/outcomes.'),(1,'Feature-based splits learned.'),(1,'New record follows branch tests.'),(1,'Leaf class prediction/appropriate evaluation detail.')])
add('4:e',['A3.4.3'],'Describe how anomaly detection could flag unusual code-change records for review without proving that copyright infringement occurred.','Establish patterns in normal change features; flag records that differ substantially. Those deviations warrant investigation but are not by themselves evidence of ownership or copying.',[(1,'Compares records with normal/baseline patterns.'),(1,'Flags deviations for human review rather than proving infringement.')],status='B',source_issues=['Original implication that deviation detection identifies copyrighted code is not sufficient evidence of copying/ownership.'])
add('4:f',['A4.3.2','A4.3.4'],'Compare supervised classification and unsupervised clustering when analysing customer support requests.','Both use features to organize records. Classification learns from labelled examples to predict predefined categories, such as billing or technical support. Clustering groups similar requests without predefined outcome labels and may reveal previously unrecognized themes; clusters need interpretation.',[(1,'Shared feature-based pattern purpose.'),(1,'Classification uses labelled data.'),(1,'Predicts predefined categories with example.'),(1,'Clustering groups similarities without class labels.'),(1,'Explains discovery/interpretation distinction.')])

def prepare():
 xs=extract('SRC-002');lookup={x['key']:x for x in xs}
 for e in E:
  x=lookup[e['key']];q=x['question'];e['context_pages']=Q_PAGES[q];e['printed_pages']=[str(n) for n in x['source_pdf_pages']];e['option']='A' if q<=4 else 'B' if q<=8 else 'C' if q<=13 else 'D'
  e['assets']=[dict(kind='scanned_source_page',description='Original scanned page contains exact stem, code, table/figure and leaf wording; OCR is an aid and was visually checked.',path=f'agents/chunk-2/agent-2-papers-b/papers/SRC-002/renders/page-{n:02}.png',source_pdf_page=n,visually_verified=True) for n in Q_PAGES[q]]
  e['visual']='Read every question-bearing scanned page and checked question/mark plus all associated visuals/code. OCR errors do not replace source image.'
 return lookup

def save_ready_prefix():
 lookup=prepare();ordered=extract('SRC-002');by={e['key']:e for e in E}
 ready=[]
 for x in ordered:
  if x['key'] not in by:break
  ready.append(x)
 # Publish only full8-leaf batches; tail remains saved in source script.
 for start in range(0,(len(ready)//8)*8,8):
  src=[source_record('SRC-002',x,by[x['key']]) for x in ready[start:start+8]]
  ps=[practice(r,by[x['key']]) for r,x in zip(src,ready[start:start+8]) if r['relevance_status']!='C']
  dest=O/'batches'/f'SRC-002-b{start//8+1:03}.json';dest.write_text(json.dumps(dict(source_id='SRC-002',batch_id=dest.stem,source_questions=src,practice_questions=ps),ensure_ascii=False,indent=2))
 print('SRC002 prefix ready',len(ready),'leaves; full batches',len(ready)//8)
if __name__=='__main__':
 for e in E:
  if e.get('test_code'):exec(e['test_code'],{})
 save_ready_prefix()
